<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Builder;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\{BelongsTo,BelongsToMany,HasMany};use Illuminate\Database\Eloquent\SoftDeletes;
class Member extends Model {use HasUuids,SoftDeletes,Auditable;protected $fillable=['household_id','first_name','last_name','email','phone','status','gender','date_of_birth','join_date','address','city','state','postal_code','role','photo_url','passport_photo','emergency_contact_name','emergency_contact_phone','notes'];protected $appends=['full_name','age','initials'];protected function casts():array{return ['date_of_birth'=>'date','join_date'=>'date'];}public function getFullNameAttribute():string{return trim("{$this->first_name} {$this->last_name}");}public function getAgeAttribute():?int{return $this->date_of_birth?->age;}public function getInitialsAttribute():string{return strtoupper(substr($this->first_name,0,1).substr($this->last_name,0,1));}public function household():BelongsTo{return $this->belongsTo(Household::class);}public function ministryGroups():BelongsToMany{return $this->belongsToMany(MinistryGroup::class)->withPivot(['joined_at','role'])->withTimestamps();}public function attendanceRecords():HasMany{return $this->hasMany(AttendanceRecord::class);}public function donations():HasMany{return $this->hasMany(Donation::class);}public function communications():HasMany{return $this->hasMany(Communication::class);}public function pastoralNotes():HasMany{return $this->hasMany(PastoralNote::class);}public function scopeSearch(Builder $q,?string $term):Builder{if(!$term)return $q;return $q->where(fn(Builder $b)=>$b->whereRaw('LOWER(first_name) LIKE ?', ['%'.strtolower($term).'%'])->orWhereRaw('LOWER(last_name) LIKE ?', ['%'.strtolower($term).'%'])->orWhereRaw('LOWER(email) LIKE ?', ['%'.strtolower($term).'%'])->orWhere('phone','like',"%$term%"));}}
